namespace ghidra.framework.main;



using docking.action;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatree;
using ghidra.framework.model;
using ghidra.util;
using ghidra.util;

public class ProjectDataSelectRealFileOrFolderAction : FrontendProjectTreeAction {

	private FrontEndPlugin plugin;

	public ProjectDataSelectRealFileOrFolderAction(FrontEndPlugin plugin, string group) : base("Select Real File or Folder", plugin.getName())
    {
		this.plugin = plugin;
		setPopupMenuData(new MenuData(new string[] { "Select Real File" }, group));
		setHelpLocation(new HelpLocation("FrontEndPlugin", "Select_Real_File_or_Folder"));
	}

	/* @Override */
	protected void actionPerformed(ProjectDataContext context) {

		bool isFolder = false;
		string pathname;

		try {
			if (context.getFolderCount() == 1 && context.getFileCount() == 0) {
				DomainFolder folder = context.getSelectedFolders().get(0);
				if (!(folder is LinkedDomainFolder linkedFolder)) {
					return;
				}
				isFolder = true;
				pathname = linkedFolder.getRealFolder().getPathname();
			}
			else if (context.getFileCount() == 1 && context.getFolderCount() == 0) {
				DomainFile file = context.getSelectedFiles().get(0);
				if (!(file is LinkedDomainFile linkedFile)) {
					return;
				}
				isFolder = false;
				pathname = linkedFile.getRealFile().getPathname();
			}
			else {
				return;
			}

			// Path is local to its project data tree
			plugin.showInProjectTree(context.getProjectData(), pathname, isFolder);
		}
		catch (IOException e) {
			Msg.showError(this, null, "Linked Content Error",
				"Failed to resolve linked " + (isFolder ? "folder" : "file"), e);
			return;
		}

	}

	/* @Override */
	protected bool isEnabledForContext(ProjectDataContext context) {
		bool enabled = false;
		string contentType = "Content";
		if (context.getComponent() is DataTree) {
			if (context.getFolderCount() == 1 && context.getFileCount() == 0) {
				DomainFolder folder = context.getSelectedFolders().get(0);
				if (folder is LinkedDomainFolder) {
					contentType = "Folder";
					enabled = true;
				}
			}
			else if (context.getFileCount() == 1 && context.getFolderCount() == 0) {
				DomainFile file = context.getSelectedFiles().get(0);
				if (file is LinkedDomainFile) {
					contentType = "File";
					enabled = true;
				}
			}
		}
		if (enabled) {
			setPopupMenuData(new MenuData(new string[] { "Select Real " + contentType },
				getPopupMenuData().getMenuGroup()));
		}
		return enabled;
	}
}
